-- Initial schema (design section 6). Kept portable across SQLite and
-- PostgreSQL: TEXT ids generated by garner (no autoincrement), timestamps as
-- RFC 3339 UTC TEXT, structured fields as JSON in TEXT, no dialect-specific
-- functions. Format-specific identity fields are NOT NULL with neutral
-- defaults, because NULLs never compare equal in UNIQUE constraints.

-- +goose Up
CREATE TABLE repositories (
    id   TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE
);
INSERT INTO repositories (id, name) VALUES ('default', 'default');

CREATE TABLE blobs (
    sha256     TEXT PRIMARY KEY,
    size       BIGINT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE packages (
    id                 TEXT PRIMARY KEY,
    repository_id      TEXT NOT NULL REFERENCES repositories (id),
    format             TEXT NOT NULL,
    name               TEXT NOT NULL,
    epoch              INTEGER NOT NULL DEFAULT 0,
    version            TEXT NOT NULL,
    release            TEXT NOT NULL DEFAULT '',
    arch               TEXT NOT NULL DEFAULT '',
    blob_sha256        TEXT NOT NULL REFERENCES blobs (sha256),
    signed_blob_sha256 TEXT REFERENCES blobs (sha256),
    metadata           TEXT NOT NULL DEFAULT '{}',
    origin             TEXT NOT NULL CHECK (origin IN ('upload', 'source')),
    origin_ref         TEXT NOT NULL,
    verify_status      TEXT NOT NULL,
    pinned             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at         TEXT NOT NULL,
    -- The same package with different content may exist once per file
    -- (design section 4, hashed pool paths).
    UNIQUE (repository_id, format, name, epoch, version, release, arch, blob_sha256)
);
CREATE INDEX packages_by_name ON packages (repository_id, format, name);

-- Where a package is published. The per-distribution content check of
-- design section 7 is enforced by ingest inside its transaction.
CREATE TABLE placements (
    package_id   TEXT NOT NULL REFERENCES packages (id),
    distribution TEXT NOT NULL,
    state        TEXT NOT NULL CHECK (state IN ('active', 'held', 'removed')),
    created_at   TEXT NOT NULL,
    PRIMARY KEY (package_id, distribution)
);

CREATE TABLE name_owners (
    repository_id TEXT NOT NULL REFERENCES repositories (id),
    namespace     TEXT NOT NULL,
    name          TEXT NOT NULL,
    owner         TEXT NOT NULL,
    source        TEXT NOT NULL CHECK (source IN ('first', 'config', 'manual')),
    assigned_at   TEXT NOT NULL,
    PRIMARY KEY (repository_id, namespace, name)
);

CREATE TABLE conflicts (
    id          TEXT PRIMARY KEY,
    kind        TEXT NOT NULL,
    package_ref TEXT NOT NULL,
    detail      TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    resolved_at TEXT
);

CREATE TABLE source_state (
    source       TEXT PRIMARY KEY,
    last_run     TEXT,
    last_success TEXT,
    last_error   TEXT,
    etags        TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE source_repos (
    source    TEXT NOT NULL,
    repo      TEXT NOT NULL,
    etag      TEXT NOT NULL DEFAULT '',
    last_seen TEXT NOT NULL,
    PRIMARY KEY (source, repo)
);

CREATE TABLE seen_releases (
    source       TEXT NOT NULL,
    repo         TEXT NOT NULL,
    tag          TEXT NOT NULL,
    release_id   TEXT NOT NULL,
    processed_at TEXT NOT NULL,
    PRIMARY KEY (source, repo, release_id)
);

CREATE TABLE snapshots (
    id          TEXT PRIMARY KEY,
    created_at  TEXT NOT NULL,
    config_hash TEXT NOT NULL,
    is_current  BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE snapshot_packages (
    snapshot_id  TEXT NOT NULL REFERENCES snapshots (id) ON DELETE CASCADE,
    package_id   TEXT NOT NULL REFERENCES packages (id),
    distribution TEXT NOT NULL,
    PRIMARY KEY (snapshot_id, package_id, distribution)
);

CREATE TABLE tokens (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL UNIQUE,
    owner        TEXT NOT NULL,
    scopes       TEXT NOT NULL,
    hash         TEXT NOT NULL UNIQUE,
    created_at   TEXT NOT NULL,
    last_used_at TEXT,
    revoked_at   TEXT
);

-- +goose Down
DROP TABLE tokens;
DROP TABLE snapshot_packages;
DROP TABLE snapshots;
DROP TABLE seen_releases;
DROP TABLE source_repos;
DROP TABLE source_state;
DROP TABLE conflicts;
DROP TABLE name_owners;
DROP TABLE placements;
DROP TABLE packages;
DROP TABLE blobs;
DROP TABLE repositories;
